<?php $filters=service('request')->getGet(); $filters=is_array($filters)?$filters:[]; ?>
<?= view('admin/partials/start', ['title'=>'سفارش‌ها','subtitle'=>'پردازش، ارسال و پیگیری خریدها','active'=>'orders']) ?>
<main>
<?php if ($error): ?><div class="admin-notice admin-error" role="alert"><?= esc($error) ?></div><?php endif; ?>
<form method="get" class="admin-toolbar"><input name="q" class="admin-search" type="search" placeholder="جست‌وجوی سفارش یا مشتری…" aria-label="جست‌وجوی سفارش" value="<?= esc($filters['q']??'', 'attr') ?>">
<select name="payment_status" aria-label="پرداخت" data-admin-filter><?php foreach([''=>'همه پرداخت‌ها','paid'=>'پرداخت‌شده','unpaid'=>'پرداخت‌نشده','review_required'=>'نیازمند بررسی','failed'=>'ناموفق'] as $v=>$label): ?><option value="<?= $v ?>" <?= ($filters['payment_status']??'')===$v?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select>
<select name="order_status" aria-label="وضعیت سفارش" data-admin-filter><?php foreach([''=>'همه وضعیت‌ها','processing'=>'در حال پردازش','pending_payment'=>'در انتظار پرداخت','shipped'=>'ارسال شده','delivered'=>'تحویل شده','cancelled'=>'لغو شده','payment_review'=>'بررسی پرداخت'] as $v=>$label): ?><option value="<?= $v ?>" <?= ($filters['order_status']??'')===$v?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select><button type="submit">جست‌وجو</button></form>
<nav class="admin-tabs" aria-label="وضعیت سفارش‌ها"><?php foreach([''=>'همه سفارش‌ها','pending_payment'=>'در انتظار پرداخت','processing'=>'در حال پردازش','shipped'=>'ارسال شده'] as $value=>$label): ?><a class="<?= ($filters['order_status']??'')===$value?'is-active':'' ?>" href="<?= esc(site_url('admin/orders?'.http_build_query(array_merge($filters,['order_status'=>$value,'page'=>1]))),'attr') ?>"><?= $label ?></a><?php endforeach; ?></nav>
<section class="admin-panel"><div class="admin-panel-heading"><h2>مدیریت سفارش‌ها</h2><span class="admin-muted"><?= admin_number((int)$pagination['total']) ?> سفارش</span></div>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>سفارش</th><th>مشتری</th><th>تاریخ</th><th>مبلغ (تومان)</th><th>پرداخت</th><th>وضعیت</th><th>جزئیات</th></tr></thead><tbody>
<?php foreach ($orders as $order): ?><tr><td><?= esc($order['order_number']) ?></td><td><?= esc($order['receiver_name']) ?></td><td><?= esc(admin_date($order['created_at'])) ?></td><td><?= admin_number((int)$order['total_toman']) ?></td><td><span class="admin-badge <?= $order['payment_status']==='paid'?'':'admin-badge-warning' ?>"><?= ['paid'=>'پرداخت‌شده','unpaid'=>'پرداخت‌نشده','review_required'=>'نیازمند بررسی','failed'=>'ناموفق'][$order['payment_status']]??esc($order['payment_status']) ?></span></td><td><span class="admin-badge <?= in_array($order['order_status'],['processing','pending_payment','payment_review'],true)?'admin-badge-warning':($order['order_status']==='cancelled'?'admin-badge-danger':'') ?>"><?= ['processing'=>'در حال پردازش','pending_payment'=>'در انتظار پرداخت','shipped'=>'ارسال شده','delivered'=>'تحویل شده','cancelled'=>'لغو شده','payment_review'=>'بررسی پرداخت'][$order['order_status']]??esc($order['order_status']) ?></span></td><td><a href="<?= site_url('admin/orders/'.(int)$order['id']) ?>">مشاهده</a></td></tr><?php endforeach; ?>
<?php if (!$orders): ?><tr><td colspan="7" class="admin-empty">سفارشی برای نمایش وجود ندارد.</td></tr><?php endif; ?></tbody></table></div><?= view('admin/partials/pagination',['pagination'=>$pagination,'path'=>'admin/orders']) ?></section></main><?= view('admin/partials/end') ?>
